import asyncio
import json
import logging
import time
import uuid
from pathlib import Path
from typing import Any, Self

import openai
from fastapi import APIRouter, HTTPException
from openai import OpenAIError
from pydantic import BaseModel, Field, model_validator

from app import hermes

router = APIRouter(tags=["solution"])

logger = logging.getLogger("uvicorn.error")

PROMPTS = Path(__file__).parent.parent / "prompts"

# The json-render catalog the client renders with, generated by client/src/catalog/catalog.test.ts.
CATALOG = json.loads((PROMPTS / "solution_catalog.json").read_text(encoding="utf-8"))

# Rules for the lesson spec Hermes returns, with the catalog filled in.
INSTRUCTIONS = (PROMPTS / "generate_solution_page.txt").read_text(encoding="utf-8").replace(
    "{{CATALOG}}", json.dumps(CATALOG, ensure_ascii=False)
)

REQUIRED_PROPS: dict[str, list[str]] = {c["name"]: c["props"].get("required", []) for c in CATALOG["components"]}

# Upper limit for one generation, even if Hermes keeps sending keepalives.
SOLUTION_TIMEOUT_SECONDS = 900


class Element(BaseModel):
    type: str
    props: dict[str, Any]
    children: list[str] = []


# A json-render spec, checked against the catalog so the client never gets a block it can't render.
# Prop types aren't checked here: each block on the client shows a short note instead of crashing on a bad prop.
class LessonSpec(BaseModel):
    root: str
    elements: dict[str, Element]

    @model_validator(mode="after")
    def fits_catalog(self) -> Self:
        if problems := catalog_problems(self):
            raise ValueError("; ".join(problems))
        return self


def catalog_problems(spec: LessonSpec) -> list[str]:
    root = spec.elements.get(spec.root)
    problems = [] if root and root.type == "Lesson" else ['"root" must be the key of the Lesson element']
    for key, element in spec.elements.items():
        if element.type not in REQUIRED_PROPS:
            problems.append(f'{key}: unknown type "{element.type}", use only {", ".join(REQUIRED_PROPS)}')
            continue
        missing = [prop for prop in REQUIRED_PROPS[element.type] if prop not in element.props]
        if missing:
            problems.append(f"{key}: {element.type} is missing {', '.join(missing)}")
        problems += [f'{key}: child "{child}" does not exist' for child in element.children if child not in spec.elements]
    return problems


class SolutionRequest(BaseModel):
    profile: dict[str, Any] = Field(description="The student's profile JSON, as returned by POST /api/profile.")


class SolutionReply(BaseModel):
    spec: dict[str, Any]


# The profile goes into the user message, fenced, so nothing in it reads as our rules.
# "<" is escaped (still valid JSON) so the student's text can't close the fence.
def profile_message(request: SolutionRequest) -> str:
    profile = json.dumps(request.profile, ensure_ascii=False, indent=2).replace("<", "\\u003c")
    return f"Build the lesson for this student.\n\n<student_profile>\n{profile}\n</student_profile>"


# Has Hermes build this student's lesson as a json-render spec, which the client renders with its catalog.
@router.post("/solution")
async def create_solution(request: SolutionRequest) -> SolutionReply:
    session_id = f"lip-solution-{uuid.uuid4()}"
    started = time.monotonic()
    spec: LessonSpec | None = None
    try:
        async with asyncio.timeout(SOLUTION_TIMEOUT_SECONDS):
            async for kind, value in hermes.stream_hermes_json(
                profile_message(request), LessonSpec, session_id=session_id, instructions=INSTRUCTIONS
            ):
                if kind == "result":
                    spec = value
    except TimeoutError:
        logger.warning("Solution generation timed out after %.0fs", time.monotonic() - started)
        raise HTTPException(status_code=504, detail="Das hat zu lange gedauert. Versuch es gleich nochmal.")
    except openai.AuthenticationError:
        # Not retryable: the HERMES_API_KEY in server/.env was rejected by the Hermes gateway.
        logger.error("Hermes rejected the API key — check HERMES_API_KEY in server/.env")
        raise HTTPException(
            status_code=502,
            detail=f"{hermes.TUTOR_NAME} ist gerade nicht erreichbar. Bitte sag dem Team Bescheid.",
        )
    except OpenAIError:
        logger.exception("Solution generation failed after %.0fs", time.monotonic() - started)
        raise HTTPException(status_code=502, detail=f"{hermes.TUTOR_NAME} antwortet gerade nicht. Versuch es nochmal.")
    except hermes.HermesError:
        logger.exception("No valid lesson spec after %.0fs", time.monotonic() - started)
        raise HTTPException(status_code=502, detail="Deine Seite konnte nicht gebaut werden. Versuch es nochmal.")

    if spec is None:  # stream_hermes_json always ends in a result or an error; kept for the type checker
        raise HTTPException(status_code=502, detail="Deine Seite konnte nicht gebaut werden. Versuch es nochmal.")
    logger.info("Solution spec %s built in %.0fs", session_id, time.monotonic() - started)
    return SolutionReply(spec=spec.model_dump())
